const decisions={
 "Syslog": [
  "Recognize a protocol for sending event notifications from systems/devices to collectors.",
  "Qualified as event-message transport/format vocabulary, distinct from storage, aggregation or detection.",
  "Central collection is a common deployment; relays and transports vary. No mandatory central topology, encryption, delivery guarantee or verified alert."
 ],
 "NetFlow": [
  "Recognize IP flow telemetry represented through metadata.",
  "Qualified as flow-summary vocabulary, distinct from full packet contents and syslog event messages.",
  "Versions, templates, sampling and export settings govern fields and completeness; no all-packet accounting, payload capture or IPFIX identity union."
 ],
 "Log Aggregation": [
  "Recognize central collection of logs from multiple sources for later use.",
  "Qualified as collection vocabulary supporting search, alerting and investigation, not their guaranteed execution.",
  "Aggregation alone does not supply correlation, detection, complete source coverage, trustworthy timestamps or log integrity."
 ],
 "Log Integrity": [
  "Recognize the intended protection of log records but hold the complete proof claim.",
  "HOLD: controls such as hashing are described as proving logs were not altered, deleted or tampered with without a protected baseline or completeness evidence.",
  "Hashes can compare retained bytes against a trusted prior digest; they alone do not establish that no log/file/event was deleted or omitted. No wording repair, deletion-proof claim or integrity outcome."
 ],
 "Playbook / Runbook": [
  "Recognize two procedure labels but hold the complete combined card.",
  "HOLD: one step-by-step incident-task definition supplies no component distinction or relationship for Playbook versus Runbook.",
  "Terms vary by organization/tool; do not invent universal human-versus-automation or broad-versus-detailed rules. Labels alone do not establish interchangeable procedures, executed response or separately assessed components."
 ],
 "Containment": [
  "Recognize isolation/restriction intended to limit incident spread or further damage.",
  "Qualified as a response purpose, distinct from removing attacker presence or recovering service.",
  "Strategy balances risk, evidence and operational impact; no mandatory shutdown, linear phase order, demonstrated isolation or guaranteed prevention of spread."
 ],
 "Eradication": [
  "Recognize removal of malware, attacker access and incident-related artifacts.",
  "Qualified as a response purpose, distinct from containment and restored service.",
  "Evidence must be preserved where appropriate; removal may involve remediation/rebuild/access changes. No deletion of every forensic artifact, proven attacker absence, complete root-cause repair or recovered service."
 ],
 "Order of Volatility": [
  "Recognize prioritizing temporary evidence before less volatile storage.",
  "Qualified as a collection-priority principle, with RAM as an example rather than an absolute first item.",
  "Registers/cache may precede RAM; system-specific volatility, safety, relevance and feasibility matter. No universal rigid collection order, unchanged memory or complete evidence capture."
 ],
 "Chain of Custody": [
  "Recognize a chronological record of evidence collection, handling, transfers and protection.",
  "Qualified as evidence-handling documentation vocabulary, distinct from technical integrity or guaranteed admissibility.",
  "Time, place, custodians and transfer/storage details need an actual record; no authentic evidence, gap-free provenance, legal acceptance or completed investigation."
 ],
 "Legal Hold": [
  "Recognize a directive to preserve relevant records for anticipated litigation or investigation.",
  "Qualified as preservation-directive vocabulary only, distinct from a fixed retention period or automatic deletion recovery.",
  "Trigger, authority, scope and release depend on applicable process/jurisdiction; no legal advice, universal statutory duty, implementation or guaranteed compliance."
 ],
 "Memory Dump": [
  "Recognize capturing RAM for subsequent analysis of live-system artifacts.",
  "Qualified as volatile-memory acquisition vocabulary, not a disk image or guarantee of particular secrets/artifacts.",
  "Tools and changing memory limit capture; acquisition may alter RAM. No perfect snapshot, all credentials/connections/injected code present, maliciousness determination or sensitive-data export."
 ]
};
